use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct Observation {
    pub url: String,
    pub title: String,
    pub viewport: [u32; 2],
    #[serde(skip_serializing_if = "Option::is_none")]
    pub focused: Option<String>,
    pub visible_text: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub state_hash: Option<String>,
    #[serde(default)]
    pub elements: Vec<ElementRef>,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct ElementRef {
    pub id: String,
    pub role: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub name: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub value: Option<String>,
    pub bbox: [f64; 4],
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub flags: Vec<String>,
}

#[derive(Clone, Debug, Serialize, Deserialize, JsonSchema, PartialEq)]
#[serde(tag = "type", rename_all = "snake_case", deny_unknown_fields)]
pub enum Action {
    Click { id: String },
    Type {
        id: String,
        text: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        submit: Option<bool>,
    },
    Select { id: String, value: String },
    Scroll { dx: i64, dy: i64 },
    Wait { ms: u64 },
    Navigate { url: String },
    Back,
    Extract {
        query: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        id: Option<String>,
    },
    Done { summary: String },
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct StepError {
    pub code: String,
    pub message: String,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct ExtractResult {
    pub query: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub id: Option<String>,
    pub value: String,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct StepResult {
    pub ok: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub error: Option<StepError>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub new_state_hash: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub extract: Option<ExtractResult>,
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn action_round_trip_click() {
        let action = Action::Click {
            id: "el_42".to_string(),
        };
        let value = serde_json::to_value(&action).expect("serialize action");
        assert_eq!(value, json!({"type": "click", "id": "el_42"}));
        let parsed: Action = serde_json::from_value(value).expect("deserialize action");
        assert_eq!(parsed, action);
    }

    #[test]
    fn action_rejects_unknown_type() {
        let value = json!({"type": "teleport", "id": "el_1"});
        let parsed: Result<Action, _> = serde_json::from_value(value);
        assert!(parsed.is_err(), "expected unknown action type to fail");
    }

    #[test]
    fn action_requires_type_tag() {
        let value = json!({"id": "el_1"});
        let parsed: Result<Action, _> = serde_json::from_value(value);
        assert!(parsed.is_err(), "expected missing type tag to fail");
    }

    #[test]
    fn observation_round_trip() {
        let observation = Observation {
            url: "https://example.com".to_string(),
            title: "Example".to_string(),
            viewport: [1280, 800],
            focused: Some("el_7".to_string()),
            visible_text: "Hello".to_string(),
            state_hash: Some("ab12cd".to_string()),
            elements: vec![ElementRef {
                id: "el_7".to_string(),
                role: "textbox".to_string(),
                name: Some("Email".to_string()),
                value: None,
                bbox: [10.0, 120.0, 400.0, 36.0],
                flags: vec!["focusable".to_string()],
            }],
        };
        let value = serde_json::to_value(&observation).expect("serialize observation");
        let parsed: Observation =
            serde_json::from_value(value).expect("deserialize observation");
        assert_eq!(parsed, observation);
    }

    #[test]
    fn step_result_round_trip() {
        let result = StepResult {
            ok: false,
            error: Some(StepError {
                code: "invalid_action".to_string(),
                message: "missing id".to_string(),
            }),
            new_state_hash: None,
            extract: None,
        };
        let value = serde_json::to_value(&result).expect("serialize step result");
        let parsed: StepResult = serde_json::from_value(value).expect("deserialize step result");
        assert_eq!(parsed, result);
    }

    #[test]
    fn step_result_with_extract_round_trip() {
        let result = StepResult {
            ok: true,
            error: None,
            new_state_hash: None,
            extract: Some(ExtractResult {
                query: "price".to_string(),
                id: Some("el_4".to_string()),
                value: "$10".to_string(),
            }),
        };
        let value = serde_json::to_value(&result).expect("serialize step result");
        let parsed: StepResult = serde_json::from_value(value).expect("deserialize step result");
        assert_eq!(parsed, result);
    }
}

use crate::types::Action;
use jsonschema::{Draft, JSONSchema};
use schemars::schema_for;
use serde_json::Value;

pub struct ActionSchema {
    schema: Value,
    validator: JSONSchema,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SchemaViolation {
    pub instance_path: String,
    pub schema_path: String,
    pub message: String,
}

impl SchemaViolation {
    fn from_error(error: jsonschema::ValidationError) -> Self {
        Self {
            instance_path: error.instance_path.to_string(),
            schema_path: error.schema_path.to_string(),
            message: error.to_string(),
        }
    }
}

impl ActionSchema {
    pub fn new() -> Self {
        let root = schema_for!(Action);
        let schema = serde_json::to_value(&root).expect("action schema to be serializable");
        let validator = JSONSchema::options()
            .with_draft(Draft::Draft7)
            .compile(&schema)
            .expect("action schema to be valid");
        Self { schema, validator }
    }

    pub fn json(&self) -> &Value {
        &self.schema
    }

    pub fn validate_json(&self, value: &Value) -> Result<(), Vec<SchemaViolation>> {
        match self.validator.validate(value) {
            Ok(()) => Ok(()),
            Err(errors) => Err(errors.map(SchemaViolation::from_error).collect()),
        }
    }
}

impl Default for ActionSchema {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn schema_accepts_all_action_variants() {
        let schema = ActionSchema::new();
        let samples = vec![
            json!({"type": "click", "id": "el_1"}),
            json!({"type": "type", "id": "el_2", "text": "hello"}),
            json!({"type": "type", "id": "el_2", "text": "hello", "submit": true}),
            json!({"type": "select", "id": "el_3", "value": "option"}),
            json!({"type": "scroll", "dx": 10, "dy": -20}),
            json!({"type": "wait", "ms": 500}),
            json!({"type": "navigate", "url": "https://example.com"}),
            json!({"type": "back"}),
            json!({"type": "extract", "query": "price"}),
            json!({"type": "extract", "query": "price", "id": "el_4"}),
            json!({"type": "done", "summary": "Finished"}),
        ];
        for sample in samples {
            assert!(
                schema.validate_json(&sample).is_ok(),
                "expected valid action, got error: {sample:?}"
            );
        }
    }

    #[test]
    fn schema_rejects_invalid_actions() {
        let schema = ActionSchema::new();
        let samples = vec![
            json!({"type": "click"}),
            json!({"type": "click", "id": "el_1", "extra": 1}),
            json!({"type": "type", "id": "el_2"}),
            json!({"type": "select", "id": "el_3"}),
            json!({"type": "scroll", "dx": 0}),
            json!({"type": "wait"}),
            json!({"type": "wait", "ms": "fast"}),
            json!({"type": "navigate"}),
            json!({"type": "extract"}),
            json!({"type": "done"}),
            json!({"type": "back", "extra": true}),
            json!({"type": "unknown"}),
        ];
        for sample in samples {
            assert!(
                schema.validate_json(&sample).is_err(),
                "expected invalid action, got ok: {sample:?}"
            );
        }
    }
}

